function animatePlanAssembly(){
 if(window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;
 const content=root.querySelector('[data-plan-content]');
 content?.classList.remove('mso-assembling');
 void content?.offsetWidth;
 content?.classList.add('mso-assembling');
 setTimeout(()=>content?.classList.remove('mso-assembling'),900);
}
function animateVisibleCounters(){
 if(window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;
 root.querySelectorAll('.mso-view:not([hidden]) .mso-evidence-grid article>strong,.mso-view:not([hidden]) .mso-lb-scorecard article>strong,.mso-view:not([hidden]) .mso-lb-friction article>strong').forEach(element=>{
  if(element.dataset.counted)return;
  const node=Array.from(element.childNodes).find(item=>item.nodeType===Node.TEXT_NODE&&/\d/.test(item.textContent));
  if(!node)return;
  const match=node.textContent.match(/^(\s*[$~]?)([\d,]+)(.*)$/);
  if(!match)return;
  element.dataset.counted='true';
  const [,prefix,raw,suffix]=match,target=Number(raw.replaceAll(',','')),duration=650,start=performance.now();
  const frame=now=>{const t=Math.min(1,(now-start)/duration),eased=1-Math.pow(1-t,3);node.textContent=prefix+Math.round(target*eased).toLocaleString()+suffix;if(t<1)requestAnimationFrame(frame)};
  requestAnimationFrame(frame);
 });
}
