 body.append(chatFlow);window.MojoAddChatSuggestions?.(chatFlow,['Adjust the audience','Change the budget','Set a stronger success rule']);chatFlow.scrollIntoView({block:'start',behavior:'smooth'});
 chatFlow.querySelector('form').addEventListener('submit',event=>{event.preventDefault();const data=new FormData(event.currentTarget);const changes=Object.fromEntries(['title','goal','audience','channels','success','holdout','signal','outcome'].map(k=>[k,String(data.get(k)).trim()]));changes.budget=Number(data.get('budget'));changes.duration=Number(data.get('duration'));changes.changedAt=new Date().toLocaleTimeString([], {hour:'numeric',minute:'2-digit'});state.edits[id]=changes;save();render();chatFlow.remove();openPlanBrief(true);});
