function openPlanBrief(immediate=false){
 const id=selected();if(!id)return;
 window.MojoOpenChat?.('',false);
 const body=document.querySelector('.chatpane .chatbody');if(!body)return;
 body.querySelectorAll('.mso-plan-chat-brief,.mso-plan-chat-wait,.seq-chat-empty,.mso-chat-flow,.mojo-why-answer').forEach(node=>node.remove());
 const wait=document.createElement('div');wait.className='mso-plan-chat-wait';wait.setAttribute('role','status');wait.setAttribute('aria-label','Loading the campaign brief');wait.innerHTML='<i></i><i></i><i></i>';body.append(wait);wait.scrollIntoView({block:'nearest'});
 const show=()=>{
  if(!wait.isConnected)return;
  let review=null;try{review=JSON.parse(localStorage.getItem('mojo-initiative-review-v1')||'null')}catch{}
  const defaults={buying_group:'Land',regional:'Demand',capture:'Brand',customer_growth:'Expand'};
  const ids={buying_group:'acceleration',regional:'coverage',capture:'visibility',customer_growth:'expansion'};
  const p=planFor(id),meta=optionMeta[id],initiative=review?.goals?.find(item=>item.id===ids[state.area]),goal=initiative?.title||defaults[state.area];
  const brief=document.createElement('section');brief.className='mso-plan-chat-brief';
  brief.innerHTML=`<span class="mso-brief-eyebrow">Campaign brief · ${esc(initiative?.initiative||defaults[state.area])}</span><h2>${esc(p.title)}</h2>
    <div class="mso-brief-block"><strong>What and why</strong><p>${esc(p.goal)}. ${esc(areaRecommendations[state.area].reason)} This supports “${esc(goal)}.”</p></div>
    <div class="mso-brief-block"><strong>How to run it</strong><dl><div><dt>Audience</dt><dd>${esc(p.audience)}</dd></div><div><dt>Message</dt><dd>${esc(meta.creative)}</dd></div><div><dt>Channels</dt><dd>${esc(p.channels)}</dd></div><div><dt>Spend</dt><dd>${money(p.budget)} over ${esc(p.duration)} days</dd></div></dl></div>
    <div class="mso-brief-block"><strong>How to know it worked</strong><p>${esc(p.success)}</p><dl><div><dt>Track</dt><dd>Campaign IDs on creative and links; verify conversion events in QA.</dd></div><div><dt>Validate</dt><dd>${esc(p.outcome)}</dd></div><div><dt>Compare</dt><dd>${esc(p.holdout)}</dd></div></dl></div>
    <div class="mso-brief-actions"><button type="button" data-brief-build>Start Building this Campaign →</button><button type="button" data-brief-refine>Refine brief</button></div>`;
  wait.replaceWith(brief);brief.scrollIntoView({block:'nearest',behavior:'smooth'});
  brief.querySelector('[data-brief-build]').addEventListener('click',savePlanToBuild);
  brief.querySelector('[data-brief-refine]').addEventListener('click',()=>{brief.remove();refine(id)});
 };
 if(immediate)show();else setTimeout(show,480);
}
